1	<!doctype html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Calculator</title>
7	<style>
8	  * { box-sizing: border-box; }
9	  body {
10	    margin: 0; min-height: 100vh; display: grid; place-items: center;
11	    background: #eef0f3; font-family: system-ui, -apple-system, sans-serif;
12	  }
13	  .calc {
14	    width: min(320px, 92vw); padding: 16px; border-radius: 16px;
15	    background: #1f2329; box-shadow: 0 10px 30px rgba(0,0,0,.25);
16	  }
17	  .display {
18	    height: 72px; margin-bottom: 12px; padding: 0 12px; border-radius: 10px;
19	    background: #2c323a; color: #fff; font-size: 2.2rem;
20	    display: flex; align-items: center; justify-content: flex-end;
21	    overflow: hidden; white-space: nowrap;
22	  }
23	  .keys { display: grid; grid-template-columns: repeat(4, 1fr); gap: 8px; }
24	  button {
25	    height: 60px; border: 0; border-radius: 10px; font-size: 1.3rem;
26	    background: #3a414b; color: #fff; cursor: pointer;
27	  }
28	  button:active { filter: brightness(1.2); }
29	  .op { background: #f59e0b; }
30	  .clear { background: #6b7280; }
31	  .equals { background: #10b981; }
32	  .wide { grid-column: span 2; }
33	  .mem-row { height: 18px; margin-bottom: 4px; padding: 0 12px; font-size: .8rem; color: #6b7280; text-align: right; }
34	  .mem-indicator[data-active="false"] { visibility: hidden; }
35	  .mem { background: #2c323a; font-size: 1.05rem; }
36	  .tape { margin-top: 12px; padding: 8px 12px; border-radius: 10px; background: #2c323a; color: #fff; }
37	  .tape-head { display: flex; align-items: center; justify-content: space-between; color: #9ca3af; font-size: .85rem; }
38	  .tape-clear { height: auto; padding: 4px 10px; font-size: .85rem; background: #3a414b; }
39	  .tape-list { max-height: 180px; overflow-y: auto; }
40	  .tape-row { display: flex; justify-content: space-between; gap: 12px; padding: 6px 0; border-top: 1px solid #3a414b; }
41	  .tape-row:first-child { border-top: 0; }
42	  .tape-expr { color: #9ca3af; overflow-wrap: anywhere; }
43	  .tape-result { white-space: nowrap; }
44	</style>
45	</head>
46	<body>
47	<div class="calc">
48	  <div class="mem-row"><span class="mem-indicator" data-testid="mem-indicator" data-active="false">M</span></div>
49	  <div class="display" data-testid="calc-display" data-value="0" data-error="false">0</div>
50	  <div class="keys">
51	    <button class="mem" data-testid="key-mc" data-action="mc">MC</button>
52	    <button class="mem" data-testid="key-mr" data-action="mr">MR</button>
53	    <button class="mem wide" data-testid="key-mplus" data-action="mplus">M+</button>
54	    <button class="clear wide" data-testid="key-lparen" data-action="lparen">(</button>
55	    <button class="clear wide" data-testid="key-rparen" data-action="rparen">)</button>
56	    <button class="clear wide" data-testid="key-clear" data-action="clear">AC</button>
57	    <button class="clear" data-testid="key-sign" data-action="sign">±</button>
58	    <button class="op" data-testid="key-div" data-op="/">÷</button>
59	    <button data-testid="key-7" data-digit="7">7</button>
60	    <button data-testid="key-8" data-digit="8">8</button>
61	    <button data-testid="key-9" data-digit="9">9</button>
62	    <button class="op" data-testid="key-mul" data-op="*">×</button>
63	    <button data-testid="key-4" data-digit="4">4</button>
64	    <button data-testid="key-5" data-digit="5">5</button>
65	    <button data-testid="key-6" data-digit="6">6</button>
66	    <button class="op" data-testid="key-sub" data-op="-">−</button>
67	    <button data-testid="key-1" data-digit="1">1</button>
68	    <button data-testid="key-2" data-digit="2">2</button>
69	    <button data-testid="key-3" data-digit="3">3</button>
70	    <button class="op" data-testid="key-add" data-op="+">+</button>
71	    <button class="wide" data-testid="key-0" data-digit="0">0</button>
72	    <button data-testid="key-dot" data-action="dot">.</button>
73	    <button class="equals" data-testid="key-equals" data-action="equals">=</button>
74	  </div>
75	  <div class="tape">
76	    <div class="tape-head">
77	      <span>Tape</span>
78	      <button class="tape-clear" data-testid="tape-clear">Clear</button>
79	    </div>
80	    <div class="tape-list" data-testid="calc-tape"></div>
81	  </div>
82	</div>
83	<script>
84	  // State: acc = stored left operand, op = pending operator,
85	  // entry = digits being typed (string) or null, value = number shown,
86	  // ready = value is a finished right operand made by ± or ), not typed,
87	  // groups = saved { acc, op } of each open parenthesis, innermost last.
88	  // For the tape: expr = committed expression text per group level, innermost
89	  // last; operand = text of the current operand at that level, or null.
90	  var state = { acc: null, op: null, entry: null, value: 0, error: false, ready: false, groups: [], expr: [''], operand: null };
91	  var tape = [];
92	  // Memory survives AC. Like every stored value it is never rounded.
93	  var memory = 0;
94	  var SYMBOLS = { '+': '+', '-': '\u2212', '*': '\u00d7', '/': '\u00f7' };
95	
96	  // Expression text of one level plus its operand, without a trailing operator.
97	  function levelText(text, operand) {
98	    if (operand !== null) text += operand.replace(/\.$/, '');
99	    return text.replace(/ \S $/, '');
100	  }
101	
102	  function compute(a, op, b) {
103	    var r;
104	    if (op === '+') r = a + b;
105	    else if (op === '-') r = a - b;
106	    else if (op === '*') r = a * b;
107	    else r = a / b;
108	    if (!isFinite(r)) return NaN;
109	    return r;
110	  }
111	
112	  // Presentation only: stored values are never rounded. At most 10 significant
113	  // digits, no trailing zeros, exponential only for |n| >= 1e10 or < 1e-9.
114	  function formatNumber(n) {
115	    if (n === 0) return '0';
116	    var r = Number(n.toPrecision(10));
117	    var abs = Math.abs(r);
118	    if (abs >= 1e10 || abs < 1e-9) {
119	      return r.toExponential(9).replace(/\.?0+e/, 'e');
120	    }
121	    var exp = Number(r.toExponential(9).split('e')[1]);
122	    var s = r.toFixed(Math.max(0, 9 - exp));
123	    if (s.indexOf('.') !== -1) s = s.replace(/0+$/, '').replace(/\.$/, '');
124	    return s;
125	  }
126	
127	  function pressDigit(d) {
128	    if (state.error) return;
129	    state.ready = false;
130	    if (state.entry === null || state.entry === '0') state.entry = d;
131	    else if (state.entry === '-0') state.entry = '-' + d;
132	    else state.entry += d;
133	    state.value = Number(state.entry);
134	    state.operand = state.entry;
135	  }
136	
137	  function pressDot() {
138	    if (state.error) return;
139	    state.ready = false;
140	    if (state.entry === null) state.entry = '0';
141	    if (state.entry.indexOf('.') === -1) state.entry += '.';
142	    state.value = Number(state.entry);
143	    state.operand = state.entry;
144	  }
145	
146	  // While typing, ± toggles the sign of the typed digits so typing can go on.
147	  // Otherwise it flips the shown value; with an operator waiting, that value
148	  // becomes the right operand (5 + ± = is 0).
149	  function pressSign() {
150	    if (state.error) return;
151	    if (state.entry !== null) {
152	      state.entry = state.entry.charAt(0) === '-' ? state.entry.slice(1) : '-' + state.entry;
153	      state.value = Number(state.entry);
154	      state.operand = state.entry;
155	    } else {
156	      state.value = -state.value;
157	      state.ready = state.op !== null;
158	      if (state.operand === null) state.operand = formatNumber(state.value);
159	      else state.operand = state.operand.charAt(0) === '-' ? state.operand.slice(1) : '-' + state.operand;
160	    }
161	  }
162	
163	  function resolve() {
164	    if (state.op !== null && (state.entry !== null || state.ready)) {
165	      state.value = compute(state.acc, state.op, state.value);
166	      if (isNaN(state.value)) state.error = true;
167	    }
168	  }
169	
170	  // Immediate execution, no precedence: each operator key first finishes the
171	  // waiting operation, strictly left to right, so the display always shows a
172	  // real running result. 2 + 3 × 4 = is 20, not 14.
173	  function pressOp(op) {
174	    if (state.error) return;
175	    resolve();
176	    if (state.error) return;
177	    var top = state.expr.length - 1;
178	    var sym = ' ' + SYMBOLS[op] + ' ';
179	    if (state.operand !== null) state.expr[top] = levelText(state.expr[top], state.operand) + sym;
180	    else if (state.expr[top] !== '') state.expr[top] = state.expr[top].slice(0, -3) + sym;
181	    else state.expr[top] = formatNumber(state.value) + sym;
182	    state.operand = null;
183	    state.acc = state.value;
184	    state.op = op;
185	    state.entry = null;
186	    state.ready = false;
187	  }
188	
189	  // ( saves the waiting operation and starts a fresh one inside the group.
190	  // Inside, the same left-to-right rule applies.
191	  function pressLparen() {
192	    if (state.error) return;
193	    state.groups.push({ acc: state.acc, op: state.op });
194	    state.expr.push('');
195	    state.operand = null;
196	    state.acc = null;
197	    state.op = null;
198	    state.entry = null;
199	    state.value = 0;
200	    state.ready = false;
201	  }
202	
203	  // ) finishes the group; its result becomes the right operand of the saved
204	  // operation (2 + ( 3 × 4 ) = is 14). Ignored with no open group.
205	  function closeGroup() {
206	    resolve();
207	    if (state.error) return;
208	    var g = state.groups.pop();
209	    var inner = levelText(state.expr.pop(), state.operand);
210	    state.operand = '(' + (inner === '' ? formatNumber(state.value) : inner) + ')';
211	    state.acc = g.acc;
212	    state.op = g.op;
213	    state.entry = null;
214	    state.ready = state.op !== null;
215	  }
216	
217	  function pressRparen() {
218	    if (state.error || state.groups.length === 0) return;
219	    closeGroup();
220	  }
221	
222	  // = closes any open groups first.
223	  function pressEquals() {
224	    if (state.error) return;
225	    while (state.groups.length > 0 && !state.error) closeGroup();
226	    if (state.error) return;
227	    resolve();
228	    var text = levelText(state.expr[0], state.operand);
229	    // A calculation is complete when the expression holds at least one operator.
230	    if (!state.error && / [+\u2212\u00d7\u00f7] /.test(text)) tape.unshift({ expr: text, value: state.value });
231	    state.expr = [''];
232	    state.operand = formatNumber(state.value);
233	    state.acc = null;
234	    state.op = null;
235	    state.entry = null;
236	    state.ready = false;
237	  }
238	
239	  // M+ adds the shown value and ends typing; with an operator waiting, that
240	  // value stays the right operand. A non-finite sum is an Error and memory
241	  // keeps its old value.
242	  function pressMplus() {
243	    if (state.error) return;
244	    var sum = compute(memory, '+', state.value);
245	    if (isNaN(sum)) { state.error = true; return; }
246	    memory = sum;
247	    if (state.entry !== null) {
248	      state.entry = null;
249	      state.ready = state.op !== null;
250	    }
251	  }
252	
253	  // MR puts memory in the display as a finished operand, like ± or ).
254	  function pressMr() {
255	    if (state.error) return;
256	    state.value = memory;
257	    state.operand = formatNumber(memory);
258	    state.entry = null;
259	    state.ready = state.op !== null;
260	  }
261	
262	  function pressMc() {
263	    memory = 0;
264	  }
265	
266	  function clear() {
267	    state = { acc: null, op: null, entry: null, value: 0, error: false, ready: false, groups: [], expr: [''], operand: null };
268	  }
269	
270	  var display = document.querySelector('[data-testid="calc-display"]');
271	  var tapeList = document.querySelector('[data-testid="calc-tape"]');
272	  var memIndicator = document.querySelector('[data-testid="mem-indicator"]');
273	
274	  function renderTape() {
275	    tapeList.textContent = '';
276	    tape.forEach(function (item) {
277	      var row = document.createElement('div');
278	      row.className = 'tape-row';
279	      row.setAttribute('data-testid', 'tape-row');
280	      var expr = document.createElement('span');
281	      expr.className = 'tape-expr';
282	      expr.setAttribute('data-testid', 'tape-expr');
283	      expr.textContent = item.expr;
284	      var result = document.createElement('span');
285	      result.className = 'tape-result';
286	      result.setAttribute('data-testid', 'tape-result');
287	      result.setAttribute('data-value', String(item.value));
288	      result.textContent = formatNumber(item.value);
289	      row.appendChild(expr);
290	      row.appendChild(result);
291	      tapeList.appendChild(row);
292	    });
293	  }
294	
295	  function render() {
296	    display.setAttribute('data-value', String(state.value));
297	    display.setAttribute('data-error', state.error ? 'true' : 'false');
298	    memIndicator.setAttribute('data-active', memory !== 0 ? 'true' : 'false');
299	    if (state.error) display.textContent = 'Error';
300	    else display.textContent = state.entry !== null ? state.entry : formatNumber(state.value);
301	  }
302	
303	  document.querySelector('.keys').addEventListener('click', function (e) {
304	    var b = e.target.closest('button');
305	    if (!b) return;
306	    if (b.dataset.digit !== undefined) pressDigit(b.dataset.digit);
307	    else if (b.dataset.op) pressOp(b.dataset.op);
308	    else if (b.dataset.action === 'dot') pressDot();
309	    else if (b.dataset.action === 'sign') pressSign();
310	    else if (b.dataset.action === 'lparen') pressLparen();
311	    else if (b.dataset.action === 'rparen') pressRparen();
312	    else if (b.dataset.action === 'equals') pressEquals();
313	    else if (b.dataset.action === 'clear') clear();
314	    else if (b.dataset.action === 'mplus') pressMplus();
315	    else if (b.dataset.action === 'mr') pressMr();
316	    else if (b.dataset.action === 'mc') pressMc();
317	    render();
318	    renderTape();
319	  });
320	
321	  document.querySelector('[data-testid="tape-clear"]').addEventListener('click', function () {
322	    tape = [];
323	    renderTape();
324	  });
325	
326	  render();
327	</script>
328	</body>
329	</html>
