// √x, x² and 1/x act on the shown value at once; the result is a finished
// operand, like ± or ). A non-finite or undefined result is an Error.
function pressSci(fn) {
  if (state.error) return;
  var x = state.value, r;
  if (fn === 'sqrt') r = Math.sqrt(x);
  else if (fn === 'square') r = x * x;
  else r = 1 / x;
  if (!isFinite(r)) { state.error = true; return; }
  var text = state.operand !== null ? state.operand.replace(/\.$/, '') : formatNumber(x);
  if (!/^[\d.]+(e[+-]\d+)?$|^\(.*\)$/.test(text)) text = '(' + text + ')';
  if (fn === 'sqrt') state.operand = '√' + text;
  else if (fn === 'square') state.operand = text + '²';
  else state.operand = '1/' + text;
  state.value = r;
  state.entry = null;
  state.ready = state.op !== null;
}

