// Keyboard entry presses the matching on-screen key.
var KEYS = { '.': 'key-dot', '+': 'key-add', '-': 'key-sub', '*': 'key-mul', '/': 'key-div',
  'Enter': 'key-equals', '=': 'key-equals', 'Escape': 'key-clear' };
document.addEventListener('keydown', function (e) {
